const NavBarDrawer: React.FC<INavBarDrawerProps> = ({
  open,
  onClose,
  routes,
}) => {
  const pathName = usePathname();
  const [isServicesExpanded, setIsServicesExpanded] = useState(false);

  return (
    <Drawer
      open={open}
      onClose={onClose}
      anchor="right"
      PaperProps={{
        width: "90%",
      }}
      sx={{
        zIndex: 9999,
        "@media(max-width: 1210px)": {
          display: "block",
        },
        "@media(max-width: 560px)": {
          "& .MuiDrawer-paper": {
            width: "100% !important",
          },
        },
        "& .MuiDrawer-paper": {
          width: 445,
        },
      }}
    >
      <nav className="w-full h-full flex flex-col justify-between px-8 pb-8 bg-background overflow-scroll backdrop-blur-lg no-scrollbar">
        <div className="flex flex-col space-y-8">
          <div className="flex flex-row items-center justify-between w-full py-3.5">
            <Link href={"/"} onClick={onClose}>
              <Image src={Images.Logo} alt="Amozart" className="w-auto h-6" />
            </Link>
            <button
              onClick={onClose}
              className="flex items-center md:p-3.5 p-1.5 rounded-full bg-secondary"
              aria-pressed={open}
            >
              <Image className="w-6 h-6" src={Icons.Close} alt="close" />
            </button>
          </div>
          <div className="w-full flex flex-col space-y-1.5 ">
            {routes.map((item, idx) => {
              const isServices = item.label === "Services";

              return (
                <React.Fragment key={idx}>
                  {isServices ? (
                    <div className="flex flex-col w-full items-center">
                      <button
                        onClick={() =>
                          setIsServicesExpanded(!isServicesExpanded)
                        }
                        className={`rounded-full uppercase text-base w-full py-2.5 flex flex-row items-center justify-between cursor-pointer transition-all duration-300 ${
                          isServicesExpanded || pathName.startsWith("/services")
                            ? " text-primary font-bold"
                            : "text-foreground"
                        }`}
                      >
                        <span>{item.label}</span>
                        <svg
                          className={`w-4 h-4 transition-transform duration-300 ${
                            isServicesExpanded ? "rotate-180" : ""
                          }`}
                          viewBox="0 0 24 24"
                          fill="none"
                          stroke="currentColor"
                          strokeWidth="2.5"
                          strokeLinecap="round"
                          strokeLinejoin="round"
                        >
                          <polyline points="6 9 12 15 18 9"></polyline>
                        </svg>
                      </button>

                      {/* Collapsible Dropdown Items list */}
                      {isServicesExpanded && (
                        <div className="w-full flex flex-col gap-3 mt-3 px-1.5">
                          {servicesList.map((service, sIdx) => (
                            <Link
                              key={sIdx}
                              href={service.href}
                              onClick={onClose}
                              className="flex flex-row items-start gap-4 p-3 bg-[#f8f8f8] hover:bg-[#e1d7f1]/30 rounded-2xl border border-transparent  transition-all duration-200 text-left"
                            >
                              <div className="shrink-0 w-12 h-12 rounded-full bg-primary text-white flex items-center justify-center shadow-sm ">
                                {service.icon}
                              </div>
                              <div className="flex flex-col gap-0.5">
                                <span className="text-sm font-bold text-gray-900 leading-snug">
                                  {service.title}
                                </span>
                                <p className="text-xs text-gray-500 leading-snug">
                                  {service.desc}
                                </p>
                              </div>
                            </Link>
                          ))}
                        </div>
                      )}
                    </div>
                  ) : (
                    <Link
                      href={item.href}
                      onClick={onClose}
                      className={`rounded-2xl uppercase text-base w-full py-2.5 transition-all duration-300 ${
                        pathName === item.href
                          ? " text-primary font-bold"
                          : "text-foreground"
                      }`}
                    >
                      {item.label}
                    </Link>
                  )}

                  {idx < routes.length - 1 && (
                    <div className="w-full h-[1.5px] bg-linear-to-r from-transparent via-gray-300/70 to-transparent " />
                  )}
                </React.Fragment>
              );
            })}
          </div>
        </div>

        <div className="flex flex-row items-center justify-center gap-x-4 w-full mt-8">
          <Link
            href={`${process.env.NEXT_PUBLIC_ADMIN_BASE_MAIN_URL}/signup`}
            onClick={onClose}
            className="text-base font-bold text-primary py-2 px-4 hover:opacity-85 transition-all duration-300"
          >
            Sign Up
          </Link>
          <Link
            href={`${process.env.NEXT_PUBLIC_ADMIN_BASE_MAIN_URL}`}
            onClick={onClose}
            className="bg-linear-to-r from-[#9053F6] to-[#6739b7] text-white text-base font-bold py-2.5 px-6 rounded-full shadow-[0_8px_20px_rgba(103,57,183,0.35)] hover:shadow-[0_12px_28px_rgba(103,57,183,0.5)] hover:-translate-y-px transition-all duration-300 text-center"
          >
            Release Now
          </Link>
        </div>
      </nav>
    </Drawer>
  );
};

export default NavBarDrawer;
